import{_ as a,c as s,o,a5 as t}from"./chunks/framework.p2RKkOSy.js";const u=JSON.parse('{"title":"Messages","description":"","frontmatter":{},"headers":[],"relativePath":"devices/api/messages/index.md","filePath":"devices/api/messages/index.md"}'),i={name:"devices/api/messages/index.md"};function r(n,e,d,l,c,h){return o(),s("div",{"data-pagefind-body":!0},e[0]||(e[0]=[t('<h1 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h1><p>Messages are the core building blocks of the protocol, allowing you to send and receive data and commands to and from devices.</p><p>All messages follow a common structure, but each type of message has its own specific purpose, payload, requirements and usage.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><p>Messages all have a type, represented as a <code>uint16</code> value, which defines the structure and purpose of the message, including what headers and payload it may or should contain.</p><p>Some example message types for the device API include:</p><ul><li><a href="./13-heartbeat">13: Heartbeat</a> - A simple message to indicate the communication link is alive</li><li><a href="./34-device-status">34: Device Status</a> - A message containing various status information about the device</li><li><a href="./10008-base-page">10008: Base Page</a> - A message to draw a preset page on the device&#39;s display</li><li><a href="./10011-draw-element">10011: Draw Element</a> - A message to draw a shape on the device&#39;s display</li><li>...</li></ul><p>You can find complete documentation for the messages used as part of the device API in the sidebar of this page.</p><p>Values of <code>60,000</code> to <code>61,000</code> are currently reserved for custom use. Feel free to implement your own messages within this range.</p><h2 id="header-fields" tabindex="-1">Header fields <a class="header-anchor" href="#header-fields" aria-label="Permalink to &quot;Header fields&quot;">​</a></h2><p>Messages make use of a few common <a href="/docs/pr/19/devices/api/protocol/headers">header fields</a> that are defined at the protocol level that you&#39;ll likely want to familiarize yourself with as they are used in device messaging.</p><p>Such as:</p><ul><li><a href="./../protocol/headers#_1-message-id">1: Message ID</a> for uniquely identifying messages</li><li><a href="./../protocol/headers#_3-response-to">3: Response to</a> for linking responses to requests</li><li><a href="./../protocol/headers#_4-status">4: Status</a> for indicating the status of a message</li><li><a href="./../protocol/headers#_5-method">5: Method</a> for optionally specifying the action to be taken</li></ul><p>You can find the full list of header fields in the <a href="/docs/pr/19/devices/api/protocol/headers">Headers documentation</a> for the protocol.</p><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><p>A method is an optional header field that can be included in messages, and is sometimes used throughout the device API.</p><p>Currently defined methods are:</p><ul><li><code>1: SET</code> - Set a value or state on the device</li><li><code>2: GET</code> - Get a value or state from the device</li><li><code>3: SUBSCRIBE</code> - Subscribe to updates for a value or state on the device</li><li><code>5: UNSUBSCRIBE</code> - Unsubscribe from updates for a value or state on the device</li></ul><p>You can find more information about these methods in the <a href="./../protocol/headers#_5-method">MH 5: Method</a> section.</p><h2 id="communication-patterns" tabindex="-1">Communication patterns <a class="header-anchor" href="#communication-patterns" aria-label="Permalink to &quot;Communication patterns&quot;">​</a></h2><p>You should receive a response to every valid and expected message when the recipient is able to process the request.</p><p>When your message includes a <a href="./../protocol/headers#_1-message-id">MH 1: Message ID</a>, the response should include the same message ID in the <a href="./../protocol/headers#_3-response-to">MH 3: Response to</a> header field.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>If you do not include a message ID, you may not receive a response</p></div><p>Responses can come in the form of a basic <a href="./5-ack">MT 5: ACK</a> or as the same message type as the request.</p><p>Responses can contain a <a href="./../protocol/headers#_4-message-status">MH 4: Response Status</a> in the header, where 0 and below are various OK responses, and anything higher than 0 indicates a warning or error.</p>',25)]))}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
